function validate([stream, pattern]) {
  if (!Array.isArray(stream) || stream.length < 1 || stream.length > 2000) return 'stream needs 1 to 2000 bits.';
  if (!Array.isArray(pattern) || pattern.length < 1 || pattern.length > 100) return 'pattern needs 1 to 100 bits.';
  if (stream.some(b => b !== 0 && b !== 1)) return 'stream contains only 0 and 1.';
  if (pattern.some(b => b !== 0 && b !== 1)) return 'pattern contains only 0 and 1.';
  const text = Array.from({ length: stream.length + pattern.length - 1 }, (_, i) => stream[i % stream.length]).join('');
  if (!text.includes(pattern.join(''))) return 'pattern must occur somewhere in the repeating stream.';
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [stream, pattern] = input;
  const limit = 100100;
  let position = 0;
  // The bits stay inside this closure; the solution can only read them one at a time with next().
  const infiniteStream = Object.freeze({
    next() {
      if (position >= limit) throw new Error('next() was called more than 100100 times; the pattern starts within the first 10^5 bits.');
      const bit = stream[position % stream.length];
      position++;
      return bit;
    },
  });
  const result = solve(infiniteStream, [...pattern]);
  if (!Number.isInteger(result)) throw new Error('Return the starting index as a whole number.');
  return result;
}

