function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 8);
  const maxM = size === 'large' ? 100 : 4;
  const density = rand() < 0.3 ? 0.9 : 0.5;
  const stream = Array.from({ length: n }, () => (rand() < density ? 1 : 0));
  const m = 1 + Math.floor(rand() * maxM);
  const occurs = pattern => Array.from({ length: n + pattern.length - 1 }, (_, i) => stream[i % n]).join('').includes(pattern.join(''));
  if (rand() < 0.5) {
    for (let tries = 0; tries < 20; tries++) {
      const pattern = Array.from({ length: m }, () => (rand() < density ? 1 : 0));
      if (occurs(pattern)) return [stream, pattern];
    }
  }
  // Otherwise copy the pattern out of the repeating stream, so it is sure to occur.
  const start = Math.floor(rand() * n);
  return [stream, Array.from({ length: m }, (_, i) => stream[(start + i) % n])];
}
